Local Functions:
static IEnumerable<int> FilterAndDouble(int[] numbers, int threshold)
{
    // Local function with closure
    bool IsAbove(int n) => n > threshold;

    int Double(int n) => n * 2;

    return numbers.Where(IsAbove).Select(Double);
}

// Local function with recursion
static int Fibonacci(int n)
{
    if (n < 0) throw new ArgumentException();
    return Fib(n);

    static int Fib(int x) => x switch
    {
        0 => 0,
        1 => 1,
        _ => Fib(x - 1) + Fib(x - 2)
    };
}

Console.WriteLine(string.Join(", ", FilterAndDouble(new[] {1,2,3,4,5}, 2)));

