IDisposable & IAsyncDisposable:
public class Resource : IDisposable, IAsyncDisposable
{
    private bool _disposed;

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        Console.WriteLine("Sync cleanup");
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        _disposed = true;
        await Task.Delay(10);
        Console.WriteLine("Async cleanup");
    }
}

// using statement
