Console.WriteLine("Using async resource...");

Variance: in/out:
using System;
using System.Collections.Generic;

// Covariance: out T — T can only be in output positions
interface IProducer<out T>
{
    T Produce();
}

class StringProducer : IProducer<string>
{
    public string Produce() => "Hello";
}

// Contravariance: in T — T can only be in input positions
interface IConsumer<in T>
{
    void Consume(T item);
}

class AnyConsumer : IConsumer<object>
{
    public void Consume(object item) =>
        Console.WriteLine($"Got: {item}");
}

// Built-in examples
class VarianceDemo
{
    public static void Demonstrate()
    {
        // Covariance: IEnumerable<out T>
        IEnumerable<string> strings = new[] { "a", "b" };
        IEnumerable<object> objects = strings;  // OK: covariant

        // Contravariance: Action<in T>
        Action<object> objAction = obj => Console.WriteLine(obj);
        Action<string> strAction = objAction;  // OK: contravariant

        // Func<out TResult> — covariant in TResult
        Func<string> stringFactory = () => "hi";
        Func<object> objectFactory = stringFactory;  // OK

        // Comparison<in T> — contravariant
        IComparer<object> objComparer = Comparer<object>.Default;
        IComparer<string> strComparer = objComparer;  // OK
    }
}

// Test custom variance
var producer = new StringProducer();
IProducer<object> objProducer = producer;  // OK: covariant
Console.WriteLine(objProducer.Produce());

var consumer = new AnyConsumer();
IConsumer<string> strConsumer = consumer;  // OK: contravariant
strConsumer.Consume("test");

