Exception Filters (when):
using System;
using System.Net.Http;

class ExceptionFilterDemo
{
    // Filter by HResult
    public static void ProcessFile(string path)
    {
        try
        {
            var content = System.IO.File.ReadAllText(path);
            Console.WriteLine(content);
        }
        catch (UnauthorizedAccessException ex) when (ex.HResult == -2147024891)
        {
            Console.WriteLine("Access denied (specific error code)");
        }
        catch (UnauthorizedAccessException ex) when (Log(ex))
        {
            Console.WriteLine("Other access error");
        }
    }

    // Filter with logging — always returns false
    static bool Log(Exception ex)
    {
        Console.WriteLine($"[Filter] {ex.GetType().Name}: {ex.Message}");
        return false;  // Don't catch, continue unwinding
    }

    // Common pattern: catch only specific HTTP status
    public static async Task FetchAsync(string url)
    {
        var client = new HttpClient();
        try
        {
            var response = await client.GetAsync(url);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            Console.WriteLine($"404: {url}");
            throw;  // Re-throw same exception
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.InternalServerError)
        {
            Console.WriteLine("Server error, retrying...");
            await FetchAsync(url);  // Retry
        }
    }
}

// Usage
try
{
    ExceptionFilterDemo.ProcessFile("/root/secret.txt");
}
catch
{
    Console.WriteLine("Unhandled exception — filter returned false, so we got here");
}

