public void ProcessOrder(string orderId, decimal amount, IEnumerable<string> items)
{
    // Traditional guards
    ArgumentNullException.ThrowIfNull(orderId);
    ArgumentNullException.ThrowIfNull(items);

    if (string.IsNullOrWhiteSpace(orderId))
        throw new ArgumentException("Order ID cannot be empty", nameof(orderId));

    if (amount <= 0)
        throw new ArgumentOutOfRangeException(nameof(amount),
            "Amount must be positive");

    // C# 11 nameof improvements
    _ = nameof(ProcessOrder);

    // Throw helper pattern (avoids inlining large cold paths)
    static void ThrowInvalidOrder(string id)
        => throw new InvalidOperationException($"Invalid order: {id}");

    if (!items.Any())
        ThrowInvalidOrder(orderId);
}

Throw Helpers:
public class Stack<T>
{
    private T[] _items;
    private int _index;

    public T Pop()
    {
        if (_index == 0)
            ThrowEmpty();

        return _items[--_index];
    }

    public T Peek()
    {
        if (_index == 0)
            ThrowEmpty();

        return _items[_index - 1];
    }

    // Throw helper - cold path kept separate
    [DoesNotReturn]
    private static void ThrowEmpty()
        => throw new InvalidOperationException("Stack is empty");
}

