Task Parallel Library (Dataflow):
static async Task DataflowPipelineAsync()
{
    var downloadBlock = new TransformBlock<string, string>(async url =>
    {
        using var client = new HttpClient();
        Console.WriteLine($"Downloading {url}");
        return await client.GetStringAsync(url);
    }, new ExecutionDataflowBlockOptions
    {
        MaxDegreeOfParallelism = 3
    });

    var processBlock = new TransformBlock<string, int>(content =>
    {
        Console.WriteLine($"Processing {content.Length} chars");
        return content.Length;
    });

    var batchBlock = new BatchBlock<int>(3);

    var writeBlock = new ActionBlock<int[]>(batch =>
    {
        Console.WriteLine($"Batch sum: {batch.Sum()}");
    });

    // Link blocks
    var linkOptions = new DataflowLinkOptions { PropagateCompletion = true };
    downloadBlock.LinkTo(processBlock, linkOptions);
    processBlock.LinkTo(batchBlock, linkOptions);
    batchBlock.LinkTo(writeBlock, linkOptions);

    // Post data
    downloadBlock.Post("https://httpbin.org/get");
    downloadBlock.Post("https://httpbin.org/uuid");
    downloadBlock.Post("https://httpbin.org/ip");
    downloadBlock.Complete();

    await writeBlock.Completion;
    Console.WriteLine("Dataflow pipeline complete");
}

Thread Synchronization:
class BankAccount
{
    private readonly object _lock = new();
    private decimal _balance;

    public void Deposit(decimal amount)
    {
        lock (_lock)
        {
            _balance += amount;
        }
    }

    public bool Withdraw(decimal amount)
    {
        lock (_lock)
        {
            if (_balance < amount) return false;
            _balance -= amount;
            return true;
        }
    }

    public decimal Balance
    {
        get { lock (_lock) { return _balance; } }
    }
}

