// ConditionalWeakTable — attach metadata
class ObjectTracker
{
    private static readonly ConditionalWeakTable<object, string> Metadata = new();

    public static void Track(object obj, string tag)
    {
        Metadata.AddOrUpdate(obj, tag);
    }

    public static string? GetTag(object obj)
    {
        return Metadata.TryGetValue(obj, out var tag) ? tag : null;
    }
}

// Weak event pattern
class EventSource
{
    private readonly ConditionalWeakTable<object, Action> _handlers = new();

    public void Subscribe(object subscriber, Action handler)
    {
        _handlers.AddOrUpdate(subscriber, handler);
    }

    public void Raise()
    {
        foreach (var (_, handler) in _handlers)
            handler();
    }
}

// Usage
var tracker = new object();
ObjectTracker.Track(tracker, "tracked-obj");
Console.WriteLine(ObjectTracker.GetTag(tracker));  // tracked-obj

