[Generator]
public class HelloGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // Register a syntax provider
        context.RegisterPostInitializationOutput(ctx =>
        {
            ctx.AddSource("Hello.g.cs",
                "// Auto-generated\n" +
                "public static class Generated\n" +
                "{\n" +
                "    public static void Hello() =>\n" +
                "        Console.WriteLine(\"Hello from source generator!\");\n" +
                "}");
        });

        // Analyze syntax trees
        var provider = context.SyntaxProvider
            .CreateSyntaxProvider(
                predicate: (node, _) => node is ClassDeclarationSyntax,
                transform: (ctx, _) => ctx.Node)
            .Where(n => n is not null);

        context.RegisterSourceOutput(provider, (spc, node) =>
        {
            // Emit code based on analysis
        });
    }
}

