using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

// Parse code
SyntaxTree tree = CSharpSyntaxTree.ParseText(@"
    public class Calculator
    {
        public int Add(int a, int b) => a + b;
    }");

// Get root
var root = (CompilationUnitSyntax)tree.GetRoot();

// Find all methods
var methods = root.DescendantNodes()
    .OfType<MethodDeclarationSyntax>()
    .ToList();

foreach (var method in methods)
{
    Console.WriteLine($"Method: {method.Identifier}");
    Console.WriteLine($"Return type: {method.ReturnType}");
    Console.WriteLine($"Parameters: {string.Join(", ", method.ParameterList.Parameters)}");
}

// Create compilation
var compilation = CSharpCompilation.Create("Demo")
    .AddReferences(MetadataReference.CreateFromFile(typeof(object).Assembly.Location))
    .AddSyntaxTrees(tree);

// Get semantic model
var model = compilation.GetSemanticModel(tree);
var typeInfo = model.GetTypeInfo(methods[0].ReturnType);
