// Large struct that would be expensive to copy
readonly struct BigData
{
    public readonly double X, Y, Z, W;
    public BigData(double x, double y, double z, double w)
    { X = x; Y = y; Z = z; W = w; }
}

// ref readonly - pass by reference, no copy, read-only guarantee
static double ComputeMagnitude(ref readonly BigData data)
{
    // Cannot modify data (compiler enforces readonly)
    // data.X = 5;  // ❌ Compile error
    return Math.Sqrt(data.X * data.X + data.Y * data.Y +
                     data.Z * data.Z + data.W * data.W);
}

// Caller - no special syntax needed (ref is implicit)
var point = new BigData(1, 2, 3, 4);
Console.WriteLine(ComputeMagnitude(in point));  // explicit in
Console.WriteLine(ComputeMagnitude(point));     // implicit ref readonly

