public void ProcessOrder(Order order)
{
    if (order is null) throw new ArgumentNullException(nameof(order));
    if (order.Items.Count == 0) throw new InvalidOperationException("Empty order");
    decimal total = 0;
    foreach (var item in order.Items)
    {
