Command-Query Separation:
// ❌ Violates CQS - both mutates and queries
public bool TryRemoveAndGetLast(List<int> list, out int last)
{
    if (list.Count == 0) return false;  // side effect + return value!
    last = list[^1];
    list.RemoveAt(list.Count - 1);
    return true;
}

// ✅ CQS-compliant: separate command from query
public static class StackOps
{
    // Query
    public static Option<int> TryPeek(IReadOnlyList<int> list)
        => list.Count > 0 ? Option<int>.Some(list[^1]) : Option<int>.None;

    // Command
    public static IReadOnlyList<int> Pop(IReadOnlyList<int> list)
        => list.Take(list.Count - 1).ToList();
}

// Usage - compose query + command explicitly
var list = new List<int> { 1, 2, 3 };
var last = StackOps.TryPeek(list);
if (last.HasValue)
{
    Console.WriteLine(last.Value);
    list = StackOps.Pop(list).ToList();
}

public record Option<T>(bool HasValue, T? Value)
{
    public static Option<T> Some(T value) => new(true, value);
    public static Option<T> None => new(false, default);
}

