// ❌ Impure - depends on external state + has side effect
public class DiscountService
{
    private static int _callCount;
    private static readonly decimal[] _tiers = [0, 0.05m, 0.10m];

    public decimal ApplyDiscount(Order order)
    {
        // Side effect
        _callCount++;

        // Depends on DateTime.Now (hidden input)
        var isWeekend = DateTime.Now.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;

        // Logic mixed with mutation
        order.DiscountApplied = true;
        return order.Total * (isWeekend ? _tiers[2] : _tiers[1]);
    }
}

// ✅ Pure function - all inputs explicit, no side effects
public static class DiscountCalculator
{
    public static decimal CalculateDiscount(decimal total, bool isWeekend, DiscountTier tier)
    {
        var rate = isWeekend ? tier.WeekendRate : tier.WeekdayRate;
        return total * rate;
    }
}

public record DiscountTier(decimal WeekdayRate, decimal WeekendRate);

