// ❌ High complexity (nested ifs, multiple conditions, else branches)
public string ClassifyCustomer(Customer c)
{
    if (c is not null)
    {
        if (c.Orders.Count > 10)
        {
            if (c.TotalSpent > 1000m)
                return "Gold";
            else
                return "Silver";
        }
        else
        {
            if (c.TotalSpent > 500m)
                return "Silver";
            else
                return "Bronze";
        }
    }
    else
        throw new ArgumentNullException(nameof(c));
}

// ✅ Low complexity: guards + extracted decisions + ternary
public string ClassifyCustomer(Customer c)
{
    ArgumentNullException.ThrowIfNull(c);

    if (c.Orders.Count <= 10 && c.TotalSpent <= 500m) return "Bronze";
    if (c.Orders.Count > 10 && c.TotalSpent > 1000m) return "Gold";
    return "Silver";
}

// Alternative: table-driven (zero complexity)
private static readonly (int MinOrders, decimal MinSpent, string Tier)[] _tiers =
[
    (10, 1000m, "Gold"),
    (0, 500m, "Silver"),
    (0, 0m, "Bronze")
];

public string ClassifyCustomerTable(Customer c)
{
    ArgumentNullException.ThrowIfNull(c);
    return _tiers.First(t => c.Orders.Count >= t.MinOrders && c.TotalSpent >= t.MinSpent).Tier;
}

