Postel's Law & Defensive Coding:
public class EmailNormalizer
{
    // Liberal input acceptance
    public static Email Normalize(string? input)
    {
        // Accept null, empty, malformed without crashing
        if (string.IsNullOrWhiteSpace(input))
            return Email.Empty;

        var trimmed = input.Trim();
        var lower = trimmed.ToLowerInvariant();

        if (!lower.Contains('@'))
            return Email.Empty;

        var parts = lower.Split('@');
        if (parts.Length != 2 || string.IsNullOrEmpty(parts[0]) || string.IsNullOrEmpty(parts[1]))
            return Email.Empty;

        // Conservative output: always produce valid Email value
        return new Email(parts[0], parts[1], lower);
    }
}

public record Email(string LocalPart, string Domain, string Full)
{
    public static readonly Email Empty = new("", "", "");

    // Conservative output: never produce null
    public override string ToString() => Full;
}

// Usage
Console.WriteLine(EmailNormalizer.Normalize("  Alice@Example.COM "));  // alice@example.com
Console.WriteLine(EmailNormalizer.Normalize(null));                     // (empty)
Console.WriteLine(EmailNormalizer.Normalize("not-an-email"));           // (empty)

